1	import { describe, expect, it } from 'vitest';
2	import fs from 'node:fs';
3	import path from 'node:path';
4	import { fileURLToPath } from 'node:url';
5	import { validateSpec } from './validate.js';
6	
7	const here = path.dirname(fileURLToPath(import.meta.url));
8	
9	function fullSpec(overrides: Partial<Record<string, string>> = {}): string {
10	  const sections: Record<string, string> = {
11	    tier: `### 5.1 Risk tier
12	
13	- **Tier**: limited
14	- **Justification**: Chatbot answering policy questions; no automated decisions about people.
15	- **Sign-off**: not required (tier below high)`,
16	    data: `### 5.2 Data provenance & privacy
17	
18	- **Data sources**: internal policy docs; user questions at runtime
19	- **PII involved?**: no
20	- **Retention**: prompts kept 30 days, then hard-deleted
21	- **Used for training?**: no; provider training disabled`,
22	    oversight: `### 5.3 Human oversight
23	
24	- **Automation level**: assistive
25	- **Override path**: support team can correct answers via admin panel
26	- **Kill switch**: feature flag chat_enabled, ops on-call, off within 5 minutes`,
27	    evaluation: `### 5.4 Evaluation plan
28	
29	- **Pre-ship metrics & thresholds**: groundedness >= 0.85; refusal rate <= 2%
30	- **Eval dataset**: eval/policy-qa.jsonl, 300 questions from real support tickets
31	- **Who runs it and when**: CI on every prompt change`,
32	    bias: `### 5.5 Bias & fairness
33	
34	- **Groups at risk of disparate impact**: non-native English speakers
35	- **Mitigations**: multilingual eval slice; simplified-language prompt rule
36	- **How tested**: disaggregated groundedness by question language`,
37	    monitoring: `### 5.6 Monitoring & rollback
38	
39	- **Production monitoring**: thumbs-down rate, refusal rate, latency
40	- **Degradation definition**: thumbs-down > 10% over 24h
41	- **Rollback trigger & procedure**: on-call flips chat_enabled off; users see the legacy FAQ`,
42	    transparency: `### 5.7 Transparency & incident response
43	
44	- **User disclosure**: "AI assistant" label in the chat header
45	- **Incident owner**: Dana Rivers (support-eng rotation)
46	- **Incident path**: in-chat report -> triage queue -> fix or disable, response within 24h`
47	  };
48	  Object.assign(sections, overrides);
49	  return `# Spec: Policy Chatbot
50	
51	## 1. Objective
52	
53	Answer policy questions.
54	
55	## 5. Responsible AI Gate
56	
57	${Object.values(sections).join('\n\n')}
58	
59	## 6. Rollout
60	
61	Later.`;
62	}
63	
64	describe('validateSpec', () => {
65	  it('blocks a spec with no gate section', () => {
66	    const result = validateSpec('# Spec\n\n## Objective\n\nBuild a thing.');
67	    expect(result.verdict).toBe('BLOCK');
68	    expect(result.findings[0].checkId).toBe('structure');
69	  });
70	
71	  it('passes a fully answered gate', () => {
72	    const result = validateSpec(fullSpec());
73	    expect(result.findings).toEqual([]);
